    "source": "/// Bellman-Ford — complete Rust reference. Returns (dist, parent, neg_cycle).\npub struct Edge {\n    pub u: usize,\n    pub v: usize,\n    pub w: f64,\n}\n\npub fn bellman_ford(n: usize, edges: &[Edge], start: usize) -> (Vec<f64>, Vec<i64>, bool) {\n    const INF: f64 = f64::INFINITY;\n    let mut dist = vec![INF; n];\n    let mut parent = vec![-1i64; n];\n    dist[start] = 0.0;\n    for _ in 0..n.saturating_sub(1) {\n        for e in edges {\n            if dist[e.u] + e.w < dist[e.v] {\n                dist[e.v] = dist[e.u] + e.w;\n                parent[e.v] = e.u as i64;\n            }\n        }\n    }\n    let mut neg_cycle = false;\n    for e in edges {\n        if dist[e.u] + e.w < dist[e.v] {\n            neg_cycle = true;\n            break;\n        }\n    }\n    (dist, parent, neg_cycle)\n}\n",
