    "source": "package algorithms\n\nimport \"math\"\n\n// Edge is a directed weighted edge U→V.\ntype Edge struct {\n\tU, V int\n\tW    float64\n}\n\n// bellmanFord — Bellman-Ford, complete Go reference. Returns (dist, parent, negCycle).\nfunc bellmanFord(n int, edges []Edge, start int) ([]float64, []int, bool) {\n\tINF := math.Inf(1)\n\tdist := make([]float64, n)\n\tparent := make([]int, n)\n\tfor i := range dist {\n\t\tdist[i], parent[i] = INF, -1\n\t}\n\tdist[start] = 0\n\tfor i := 0; i < n-1; i++ {\n\t\tfor _, e := range edges {\n\t\t\tif dist[e.U]+e.W < dist[e.V] {\n\t\t\t\tdist[e.V] = dist[e.U] + e.W\n\t\t\t\tparent[e.V] = e.U\n\t\t\t}\n\t\t}\n\t}\n\tnegCycle := false\n\tfor _, e := range edges {\n\t\tif dist[e.U]+e.W < dist[e.V] {\n\t\t\tnegCycle = true\n\t\t\tbreak\n\t\t}\n\t}\n\treturn dist, parent, negCycle\n}\n",
